-- Job order matrix: Device Repair
-- Generated by backend/scripts/jobMatrixToSql.ts from prisma/seeds/data/jobOrderMatrix.json.
-- Paste the whole file into the Neon SQL editor and run it once.
-- Everything runs in one transaction: if any statement fails, nothing is kept.
-- Fills an EMPTY category only (it stops if the category already has jobs).
-- To undo: device-repair-undo.sql

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "ServiceType" WHERE name = 'Device Repair') THEN
    RAISE EXCEPTION 'No service category named Device Repair';
  END IF;
  IF EXISTS (SELECT 1 FROM "ServiceTask" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair')) THEN
    RAISE EXCEPTION 'Device Repair already has jobs; nothing was changed. Use scripts/applyJobMatrix.ts for a category with jobs.';
  END IF;
END $$;

-- Starting price on the category tile: the cheapest job.
UPDATE "ServiceType" SET "basePrice" = 350 WHERE name = 'Device Repair';

-- Remove the old category-wide questions (and their options/worker match choices).
DELETE FROM "ServiceScopeField" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair');

-- Jobs (11). Worker price range = 80%–150% of the standard price.
SELECT v.id, (SELECT id FROM "ServiceType" WHERE name = 'Device Repair'), v.name, v.sort_order, v.base_price, v.pricing_model::"TaskPricingModel", v.min_price, v.max_price, v.unit, true
FROM (VALUES
  ('cb037f971513863065a6a560e', 'Diagnosis / Checkup / Repair Attempt Fee', 0, 350::double precision, 'PER_UNIT', 280::double precision, 525::double precision, 'device'),
  ('c8a8aee1df5986c841d562765', 'Reformat & Reinstall OS', 1, 1000::double precision, 'PER_UNIT', 800::double precision, 1500::double precision, 'device'),
