  ('c212ec3c10b2ab4be797b3ac3', 'Maintenance Cleaning', 4, 800::double precision, 'PER_UNIT', 640::double precision, 1200::double precision, 'device'),
  ('c313b9c5353fd2cdc57d66069', 'Parts Installation', 5, 800::double precision, 'PER_UNIT', 640::double precision, 1200::double precision, 'part'),
  ('ca96ef7f429de6a8420b791eb', 'PC Build / Rebuild', 6, 2000::double precision, 'PER_UNIT', 1600::double precision, 3000::double precision, 'PC'),
  ('c1e5c2027ef94e041cbe15b4f', 'Chassis / Hinge Repair', 7, 800::double precision, 'PER_UNIT', 640::double precision, 1200::double precision, 'device'),
  ('c051e874dd8496577a97b425b', 'Motherboard Level Repair', 8, 2500::double precision, 'PER_UNIT', 2000::double precision, 3750::double precision, 'device'),
  ('c7324cdd9d37501eae642bcc1', 'Networking Setup', 9, 9000::double precision, 'FIXED', 7200::double precision, 13500::double precision, 'site'),
  ('c5f1f7b7f958e196c3439ef42', 'Data Recovery Services', 10, 2000::double precision, 'PER_UNIT', 1600::double precision, 3000::double precision, 'device')
) AS v(id, name, sort_order, base_price, pricing_model, min_price, max_price, unit);

