-- Choices for Pick one / Pick any / Yes-No questions (117).

-- Which job each per-job question is asked for.

-- Per-unit jobs: the number question that sets the price.
UPDATE "ServiceTask" SET "quantityScopeFieldId" = 'c30259cf0833c9f8e5078b795' WHERE id = 'cb037f971513863065a6a560e';
UPDATE "ServiceTask" SET "quantityScopeFieldId" = 'ca9b53db02f0981c53ad7206b' WHERE id = 'c8a8aee1df5986c841d562765';
