-- Sign every VERIFIED worker in the category up for every job at the standard price.
SELECT gen_random_uuid()::text, w."workerProfileId", t.id, true, NOW()
FROM "WorkerServiceCategory" w
JOIN "ServiceTask" t ON t.id IN ('cb037f971513863065a6a560e', 'c8a8aee1df5986c841d562765', 'c1bfdce2c10ab4b54d4de13b1', 'c34939e41fa12ed98866085b5', 'c212ec3c10b2ab4be797b3ac3', 'c313b9c5353fd2cdc57d66069', 'ca96ef7f429de6a8420b791eb', 'c1e5c2027ef94e041cbe15b4f', 'c051e874dd8496577a97b425b', 'c7324cdd9d37501eae642bcc1', 'c5f1f7b7f958e196c3439ef42')
WHERE w."serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair') AND w.status = 'VERIFIED'
ON CONFLICT ("workerProfileId", "serviceTaskId") DO UPDATE SET "isActive" = true, "updatedAt" = NOW();

SELECT gen_random_uuid()::text, w."workerProfileId", t.id,
       CASE WHEN t."pricingModel" = 'FIXED' THEN t."basePrice" END,
       CASE WHEN t."pricingModel" = 'PER_UNIT' THEN t."basePrice" END,
       true, NOW()
FROM "WorkerServiceCategory" w
JOIN "ServiceTask" t ON t.id IN ('cb037f971513863065a6a560e', 'c8a8aee1df5986c841d562765', 'c1bfdce2c10ab4b54d4de13b1', 'c34939e41fa12ed98866085b5', 'c212ec3c10b2ab4be797b3ac3', 'c313b9c5353fd2cdc57d66069', 'ca96ef7f429de6a8420b791eb', 'c1e5c2027ef94e041cbe15b4f', 'c051e874dd8496577a97b425b', 'c7324cdd9d37501eae642bcc1', 'c5f1f7b7f958e196c3439ef42') AND t."pricingModel" IN ('FIXED', 'PER_UNIT')
WHERE w."serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair') AND w.status = 'VERIFIED'
ON CONFLICT ("workerProfileId", "serviceTaskId") DO UPDATE
  SET price = EXCLUDED.price, "unitPrice" = EXCLUDED."unitPrice", "isActive" = true, "updatedAt" = NOW();

-- Widen any city price caps so bookings at the new prices aren't rejected
-- (₱0 up to the largest booking x top worker tier x 1.25).
UPDATE "PricingRule"
SET "minPrice" = 0,
    "maxPrice" = GREATEST("maxPrice", CEIL(13500 * (SELECT GREATEST(COALESCE(MAX("tierProMultiplier"), 1.15), COALESCE(MAX("tierExpertMultiplier"), 1.3)) FROM "AppSettings") * 1.25 / 1000) * 1000),
    "updatedAt" = NOW()
WHERE LOWER("serviceType") = LOWER('Device Repair');

-- Summary (check these before trusting the result).
SELECT
  (SELECT COUNT(*) FROM "ServiceTask" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair') AND "isActive") AS active_jobs,          -- expect 11
  (SELECT COUNT(*) FROM "ServiceScopeField" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair')) AS questions,                       -- expect 44
  (SELECT COUNT(*) FROM "ServiceTask" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair') AND "pricingModel" = 'PER_UNIT' AND "quantityScopeFieldId" IS NULL) AS per_unit_jobs_missing_count, -- expect 0
  (SELECT COUNT(*) FROM "WorkerTaskPrice" WHERE "serviceTaskId" IN ('cb037f971513863065a6a560e', 'c8a8aee1df5986c841d562765', 'c1bfdce2c10ab4b54d4de13b1', 'c34939e41fa12ed98866085b5', 'c212ec3c10b2ab4be797b3ac3', 'c313b9c5353fd2cdc57d66069', 'ca96ef7f429de6a8420b791eb', 'c1e5c2027ef94e041cbe15b4f', 'c051e874dd8496577a97b425b', 'c7324cdd9d37501eae642bcc1', 'c5f1f7b7f958e196c3439ef42')) AS worker_prices_set;

COMMIT;
